from decimal import Decimal as D, ROUND_HALF_UP
def r(x): return x.quantize(D('0.01'), rounding=ROUND_HALF_UP)
gross=D('50750.00')
base_exp=D('10973.63')  # at 60%
def calc(l25):
    exp = base_exp - D('1116.00') + l25
    net = gross - exp
    se_net = r(net*D('0.9235')); se=r(se_net*D('0.153'))
    return exp, net, se_net, se, r(se/2)
for pct in ['0.50','0.60','1.00']:
    l25 = r(D('1860.00')*D(pct))
    print(pct, 'l25', l25, calc(l25))
PY"}
